import * as E from './engine.js?v=2';
import * as I from './identity.js?v=2';
let joinBusy=false;
const KEY='tno-demo-v1',PUB='tno-public-v1';
let s;try{s=JSON.parse(localStorage.getItem(KEY));if(s?.version!==1)s=null;}catch{}s??=E.initial();
let view='welcome',page='overview',group=0,playerId=1,roleVisible=false,privateRoles=false,guide=-1,holdTimer,toastTimer;
const $=id=>document.getElementById(id),esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const phase=()=>s.phases[s.phase],person=()=>E.getPlayer(s,playerId),time=n=>`${String(Math.floor(Math.max(0,n)/60)).padStart(2,'0')}:${String(Math.floor(Math.max(0,n)%60)).padStart(2,'0')}`;
async function joinByName(form){
  const error=$('join-error'),button=form.querySelector('button[type="submit"]');
  if(joinBusy)return;
  joinBusy=true;error.hidden=true;button.disabled=true;button.textContent='Joining…';
  try{
    const result=await I.claimName(s,$('join-name').value,$('join-pin').value,$('join-pin-confirm').value);
    playerId=result.player.id;group=result.player.group;view='cadet';roleVisible=false;
    E.record(s,`${result.player.name} ${result.returning?'returned to':'joined'} ${s.groups[group].name}.`);
    save();render();
  }catch(e){save();error.textContent=e.message;error.hidden=false;button.disabled=false;button.textContent='Join →';}
  finally{joinBusy=false;}
}
function save(){try{localStorage.setItem(KEY,JSON.stringify(s));localStorage.setItem(PUB,JSON.stringify(E.publicData(s)));}catch{toast('Device storage is unavailable. Keep this tab open; progress may not survive refresh.');}}
function toast(t){$('toast').textContent=t;$('toast').style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').style.display='none',4200);}
function action(a,txt,cls='',attrs=''){return `<button class="${cls}" data-action="${a}" ${attrs}>${txt}</button>`;}
function pill(t,c=''){return `<span class="pill ${c}">${esc(t)}</span>`;}
function brand(){return `<div class="brand"><div class="brand-mark"><span>24</span></div><div class="brand-name"><small>2427 · BIGGIN HILL</small>Trust No One</div></div>`;}
function options(players,selected){return players.map(p=>`<option value="${p.id}" ${Number(selected)===p.id?'selected':''}>${esc(p.name)}</option>`).join('');}
function heading(k,title,sub,buttons=''){const names={'A little trust. A lot of secrets.':'Control room','Every face has a story.':'Players','More than a game of suspicion.':'Missions','Let the room decide.':'Voting','What happens after dark.':'Eliminations','Leave time for the truth.':'Timetable','Every secret has an ending.':'Results','A record of the evening.':'Event log','Set the ground rules.':'Settings'};return `<div class="page-heading"><h1>${names[title]??title}</h1><div class="btns">${buttons}</div></div>`;}
function panel(title,body,extra='',cls=''){return `<section class="panel ${cls}"><div class="panel-head"><h3>${title}</h3>${extra}</div><div class="panel-body">${body}</div></section>`;}
function footer(){return `<footer class="footer"><span>2427 · Independent rehearsal demo</span><a href="guide.html" target="_blank">Help & setup ↗</a><span>Not affiliated with the BBC.</span></footer>`;}
function welcome(){return `<div class="welcome simple-welcome"><header class="welcome-nav">${brand()}${pill('LOCAL DEMO','amber')}</header><main class="welcome-main"><div class="welcome-intro"><div class="eyebrow">2427 · HALLOWEEN</div><h1>Trust<br><em>No One.</em></h1><p class="intro">Complete the missions.<br>Find the Traitors.</p><div class="btns">${action('start','Host controls','ghost')}${action('guide','Show staff the demo','ghost')}</div></div><section class="entry-panel"><h2>Join the game</h2><p class="subtitle">Your name and a four-digit PIN.</p><form id="join-form" class="stack" style="margin-top:24px"><label class="field">Your name<input id="join-name" placeholder="First name or callsign" maxlength="30" autocomplete="off" required></label><div class="form-grid"><label class="field">Create PIN<input id="join-pin" type="password" inputmode="numeric" pattern="[0-9]{4}" minlength="4" maxlength="4" autocomplete="new-password" placeholder="4 digits" required></label><label class="field">Repeat PIN<input id="join-pin-confirm" type="password" inputmode="numeric" pattern="[0-9]{4}" minlength="4" maxlength="4" autocomplete="new-password" placeholder="Same 4 digits" required></label></div><p id="join-error" class="form-error" role="alert" hidden></p><button class="gold full" type="submit">Join →</button></form><p class="tiny muted" style="margin-top:16px">Already joined? Use the same name and PIN.</p><details class="demo-details"><summary>About this demo</summary><p>Names and PIN checks are saved in this browser only. A shared database is not connected yet. Use a practice PIN.</p><a href="guide.html#backend" target="_blank">Setup notes ↗</a></details></section></main><div class="welcome-foot">${footer()}</div></div>`;}
const navs=[['overview','◈','Control room'],['groups','♜','Players'],['missions','◇','Missions'],['voting','◎','Voting'],['night','☾','Eliminations'],['schedule','◷','Timetable'],['results','✧','Results'],['log','≡','Event log'],['settings','⚙','Settings']];
function shell(content){return `<div class="app-layout"><aside class="sidebar">${brand()}<nav class="nav main-nav">${view==='cadet'?action('page','My game','active','data-page="overview"'):navs.filter(n=>view!=='nco'||['groups','missions','voting','night','log'].includes(n[0])).map(n=>action('page',`<span class="icon">${n[1]}</span>${n[2]}`,page===n[0]?'active':'',`data-page="${n[0]}"`)).join('')}</nav><div class="nav-label">DEMO TOOLS</div><nav class="nav">${action('projector','Player board ↗')}${action('guide','Staff walkthrough')}${action('welcome','Join screen')}</nav><div class="sidebar-foot"><a class="tiny" href="guide.html" target="_blank">Help & setup ↗</a></div></aside><div><header class="topbar"><span class="tiny muted">${view==='host'?'Host':view==='nco'?'Group NCO':'Cadet'} view</span><div class="row"><label class="tiny muted" for="view-switch">Preview</label><select id="view-switch" aria-label="Preview role"><option value="host" ${view==='host'?'selected':''}>Host</option><option value="nco" ${view==='nco'?'selected':''}>Group NCO</option><option value="faithful" ${view==='cadet'&&person().role!=='Traitor'&&person().status==='Active'?'selected':''}>Faithful</option><option value="traitor" ${view==='cadet'&&person().role==='Traitor'&&person().status==='Active'?'selected':''}>Traitor</option><option value="eliminated" ${view==='cadet'&&person().status!=='Active'?'selected':''}>Eliminated</option></select></div>${pill('LOCAL DEMO','amber')}</header><main class="workspace">${guide>=0?guideBar():''}${content}${footer()}</main></div></div>`;}
function phaseCard(){const p=phase();return `<section class="panel phase-card"><div class="row between"><span class="eyebrow">CURRENT PHASE</span>${pill(s.running?'RUNNING':'PAUSED',s.running?'green':'amber')}</div><h2>${esc(p.name)}</h2><div class="timer" data-timer style="margin-top:22px">${time(s.remaining)}</div><div class="row between phase-footer"><div class="btns">${action('timer',s.running?'Pause':'Start timer','gold')}${action('extend','+ 1 min','ghost')}</div>${action('advance','Next →','ghost',s.phase===12?'disabled':'')}</div></section>`;}
function stats(){const active=s.players.filter(p=>p.status==='Active').length,pending=Object.values(s.murders).filter(m=>m.confirmed&&!m.published).length+s.helps.filter(h=>!h.done).length;return `<div class="stats simple-stats"><div class="stat"><label>Players</label><strong>${s.players.length}</strong></div><div class="stat"><label>Still in</label><strong>${active}</strong></div><div class="stat"><label>Needs attention</label><strong>${pending}</strong></div></div>`;}
function groupRows(){return `<section class="panel"><div class="panel-head"><h3>Groups</h3>${action('page','Players →','small ghost','data-page="groups"')}</div><div class="group-list"><div class="simple-group-row table-labels"><span>Group</span><span>Still in</span><span>Points</span><span></span></div>${s.groups.map((g,i)=>`<div class="simple-group-row"><span>${esc(g.name)} ${g.done?pill('SOLVED','green'):''}</span><span class="muted">${E.active(s,i).length}</span><span>${g.score}</span>${action('group','›','small ghost',`data-group="${i}" aria-label="Manage ${esc(g.name)}"`)}</div>`).join('')}</div></section>`;}
function timeline(){return `<section class="panel"><div class="panel-head"><h3>Tonight’s run of show</h3>${action('page','View all ↗','small ghost','data-page="schedule"')}</div><div class="timeline">${s.phases.slice(Math.max(0,s.phase-1),Math.max(0,s.phase-1)+5).map((p,i)=>`<div class="timeline-item ${p===phase()?'current':''}"><time>${p.time}</time><span class="marker"></span><div><h4>${esc(p.name)}</h4><small>${p.mins} minutes ${p===phase()?'· current phase':''}</small></div></div>`).join('')}</div><div style="padding:0 20px 18px"><p class="tiny muted">21:05 finish · 21:10 clear up · 21:15 parade</p></div></section>`;}
function overview(){return heading('','Control room','',action('projector','Open player board ↗','gold'))+stats()+`<div class="dashboard-grid"><div class="stack">${phaseCard()}${groupRows()}</div><div class="stack">${panel('Start the game',`<p class="muted" style="margin-bottom:14px">${s.assigned?'Roles are ready.':'When everyone has joined, release the roles.'}</p>${action('assign',s.assigned?'Roles released ✓':'Close joining & release roles','gold full',s.assigned?'disabled':'')}`)}${panel('Announcement',`<p class="tiny muted">${esc(s.announcements[0]?.text)}</p><form id="announce-form" class="stack" style="margin-top:14px"><textarea id="announcement" aria-label="Announcement" maxlength="280" placeholder="Message for everyone…" required></textarea><button type="submit">Send announcement</button></form>`)}${s.helps.some(h=>!h.done)?panel('Help requests',s.helps.filter(h=>!h.done).map(h=>`<div class="row between" style="margin:8px 0"><span>${esc(E.getPlayer(s,h.id).name)}</span>${action('help-done','Done','small',`data-id="${h.id}"`)}</div>`).join('')):''}<details class="panel simple-details"><summary>Try simulated actions</summary><div class="panel-body btns">${action('sim-votes','Fill votes')}${action('sim-murder','Choose targets')}${action('disconnect','Signal loss')}</div></details></div></div>`;}
function groupTabs(){return view==='nco'?`<div class="pill amber" style="margin-bottom:20px">${esc(s.groups[group].name)}</div>`:`<div class="tab-buttons">${s.groups.map(g=>action('select-group',g.name,g.id===group?'active':'',`data-group="${g.id}"`)).join('')}</div>`;}
function groups(){
 const g=s.groups[group],people=s.players.filter(p=>p.group===group);
 const roster=`<div class="row between" style="margin-bottom:16px"><span class="muted">${people.length} players</span>${action('roles',privateRoles?'Hide roles':'Show roles','small ghost')}</div><div class="player-list">${people.map(p=>`<div class="player"><span class="avatar">${p.id}</span><div class="info">${esc(p.name)}<small>${p.status}${p.connected?'':' · Disconnected'}${p.shield?' · Shield':''}</small>${privateRoles?`<span class="roster-secret">${p.role??'Unassigned'}</span>`:''}</div>${action('player-tools','•••','ghost',`data-id="${p.id}" aria-label="Manage ${esc(p.name)}"`)}</div>`).join('')}</div>`;
 return heading('','Players','')+groupTabs()+`<div class="dashboard-grid">${panel(g.name,roster)}<div class="stack">${panel('Mission points',`<div class="timer">${g.score}</div><form id="score-form" class="stack section-gap"><label class="field">Add or subtract points<input id="score-delta" type="number" min="-999" max="999" value="25" required></label><label class="field">Reason<input id="score-reason" maxlength="160" placeholder="Mission completed…" required></label><button class="gold" type="submit">Save points</button></form>`)}${view==='host'?action('nco','Preview group NCO','ghost full'):''}${s.helps.some(h=>!h.done&&E.getPlayer(s,h.id).group===group)?panel('Help requests',s.helps.filter(h=>!h.done&&E.getPlayer(s,h.id).group===group).map(h=>`<div class="row between"><span>${esc(E.getPlayer(s,h.id).name)}</span>${action('help-done','Done','small',`data-id="${h.id}"`)}</div>`).join('')):''}</div></div>`;
}
function missions(){return heading('','Missions','','')+`<div class="card-grid">${s.missions.map((m,i)=>`<section class="panel mission-card"><span class="eyebrow">MISSION ${i+1} · ${m.points} POINTS</span><h2>${esc(m.title)}</h2><p>${esc(m.description)}</p><div class="btns">${action('mission-detail','Instructions','small',`data-index="${i}"`)}${view==='host'?action('mission-edit','Edit','small ghost',`data-index="${i}"`):''}</div></section>`).join('')}</div><div class="section-gap">${action('page','Record team points →','gold','data-page="groups"')}</div>`;}
function voting(){
 const v=s.votes[E.voteKey(s,group)],people=E.active(s,group),inPhase=phase().type==='vote';
 let result='';
 if(v?.status==='tie')result=`<div class="notice section-gap">Tie: ${v.tied.map(id=>esc(E.getPlayer(s,id).name)).join(', ')}<div class="btns section-gap">${v.runoff?action('random-tie','Random draw','gold',view==='nco'?'disabled':''):action('runoff','Open runoff','gold')}</div></div>`;
 if(v?.status==='closed')result=`<div class="notice section-gap"><h3>${v.result?esc(E.getPlayer(s,v.result).name):'No banishment'}</h3><p class="tiny muted">${v.abstentions?.length??0} abstentions · ${v.revealed?'Published':'Private result'}</p><div class="btns section-gap">${action('publish-banish','Reveal name','danger',!v.result||v.revealed||view==='nco'?'disabled':'')}${action('reveal-role','Reveal role','',!v.revealed||view==='nco'||s.lastReveal?.kind!=='Banished'||s.lastReveal.role?'disabled':'')}</div></div>`;
 return heading('','Voting','')+groupTabs()+`<div class="dashboard-grid"><div class="stack">${panel(s.groups[group].name,`<div class="row between"><span class="timer">${v?Object.keys(v.ballots).length:0}<span class="muted" style="font-size:25px"> / ${people.length}</span></span>${pill(v?.status?.toUpperCase()??'DISCUSSION','amber')}</div><p class="subtitle">${inPhase?'Votes submitted':'Move to a round table to begin.'}</p><div class="btns section-gap">${action('open-vote','Open voting','gold',!inPhase||v||s.groups[group].done?'disabled':'')}${action('close-vote','Close voting','',v?.status!=='open'?'disabled':'')}${action('extend','+ 1 min','ghost')}${action('sim-votes','Fill demo votes','ghost',v?.status!=='open'?'disabled':'')}</div>${result}`)}${panel('Who has voted',`<div class="player-list">${people.map(p=>`<div class="player"><span class="avatar">${p.id}</span><div class="info">${esc(p.name)}</div><span class="tiny muted">${v?.ballots[p.id]?'✓ Voted':'Waiting'}</span></div>`).join('')}</div>`)}</div><div class="stack">${panel('Vote for a cadet',`<form id="proxy-form" class="stack"><label class="field">Voter<select id="proxy-voter">${options(people)}</select></label><label class="field">Their choice<select id="proxy-target">${options(people.filter(p=>!v?.candidates||v.candidates.includes(p.id)))}</select></label><button type="submit" ${v?.status!=='open'?'disabled':''}>Save their vote</button></form><p class="tiny muted" style="margin-top:12px">Ask for their choice first. This action is logged.</p>`)}<details class="panel simple-details"><summary>Voting rules</summary><div class="panel-body"><p class="tiny muted">One vote per active player. No self voting. Choices can change before closure. Missing votes become abstentions. One runoff, then a host random draw. Keep accusations about game actions.</p></div></details></div></div>`;
}
function night(){
 const slot=phase().slot??0,m=s.murders[E.murderKey(group,slot)],traitors=E.active(s,group).filter(p=>p.role==='Traitor'),targets=E.active(s,group).filter(p=>p.role==='Faithful');
 return heading('','Eliminations','')+groupTabs()+`<div class="dashboard-grid"><div class="stack">${panel(`Opportunity ${slot+1}`,`<p class="tiny muted">${slot===1?'Secret mission: NCO verifies success before the next vote.':'Standard murder: agree a target, then confirm.'}</p><form id="murder-form" class="form-grid section-gap"><label class="field">Traitor<select id="murder-actor">${options(traitors)}</select></label><label class="field">Target<select id="murder-target">${options(targets,m?.target)}</select></label><button type="submit" ${!traitors.length||m?.confirmed?'disabled':''}>Save choice</button></form>${m?`<div class="notice section-gap"><h3>${esc(E.getPlayer(s,m.target)?.name??'No target')}</h3><p class="tiny muted">${m.published?'Published':m.confirmed?m.reason+' · not yet revealed':'Awaiting confirmation'}</p>${Object.entries(m.choices).map(([id,target])=>`<p class="tiny muted">${esc(E.getPlayer(s,id).name)} → ${esc(E.getPlayer(s,target).name)}</p>`).join('')}</div>`:''}<div class="btns section-gap">${action('confirm-murder',slot===1?'Confirm success':'Confirm outcome','gold',!m||m.confirmed?'disabled':'')}${slot===1?action('fail-murder','Mark failed','',!m||m.confirmed?'disabled':''):''}${action('publish-murder','Reveal on board','danger',!m?.confirmed||m.published||view==='nco'?'disabled':'')}</div><p class="tiny muted" style="margin-top:15px">The player board updates only when you reveal.</p>`)}${panel('Private instruction',`<form id="objective-form" class="stack"><label class="field">For this group’s Traitors<textarea id="objective" maxlength="280" required placeholder="Give them a secret objective…">${esc(s.objectives[group]??'')}</textarea></label><button type="submit">Send instruction</button></form>`)}</div><div class="stack">${panel('Traitor messages',s.messages.filter(m=>m.group===group).slice(-8).map(m=>`<div class="chat-message"><small>${esc(m.from)}</small><p>${esc(m.text)}</p></div>`).join('')||'<p class="muted">No messages yet.</p>')}<details class="panel simple-details"><summary>Elimination rules</summary><div class="panel-body"><p class="tiny muted">One victim per opportunity. ${s.settings.decisionMaker?'The lowest-numbered active Traitor breaks disagreements.':'Disagreement needs resolving first.'} ${s.settings.shields?'Shields block murder, not banishment.':'Shields are off.'} No replacement victim after a blocked attempt. Confirmed secret outcomes survive the acting Traitor’s banishment.</p></div></details></div></div>`;
}
function schedule(){return heading('THE RUN OF SHOW','Leave time for the truth.','Editable timings. Keep the finale at 21:05, clear up at 21:10 and parade at 21:15.',action('late','Running late?','gold'))+`<div class="dashboard-grid">${panel('Evening timetable',`<form id="schedule-form"><div class="schedule-row muted"><span>START</span><span>PHASE</span><span>MINUTES</span></div>${s.phases.map((p,i)=>`<div class="schedule-row"><input aria-label="${esc(p.name)} start" type="time" id="start-${i}" value="${p.time}" required><div>${esc(p.name)} ${i===s.phase?pill('NOW','amber'):''}${view==='host'?`<br>${action('jump','Go to phase','small ghost',`data-index="${i}"`)}`:''}</div><input aria-label="${esc(p.name)} duration" type="number" id="mins-${i}" min="1" max="60" value="${p.mins}" required></div>`).join('')}<button type="submit" class="gold section-gap">Save timetable</button></form>`)}<div class="stack">${phaseCard()}<div class="notice">Times are the planned run sheet. Starting a demo timer begins a relative countdown. Reaching zero prompts the organiser; it never advances the phase or reveals a role.</div></div></div>`;}
function results(){return heading('THE FINAL REVEAL','Every secret has an ending.','Deduction winners and physical mission scores are separate achievements.',s.ended?'':action('finish','End game & reveal winners','gold',view!=='host'?'disabled':''))+(s.ended?`<div class="results-grid">${E.results(s).map(g=>`<section class="panel result"><span class="eyebrow">${esc(g.name)}</span><h2>${g.winner} win</h2><p>${g.score} mission points</p></section>`).join('')}</div><div class="notice section-gap">Highest-scoring mission team${s.groups.filter(g=>g.score===Math.max(...s.groups.map(x=>x.score))).length>1?'s (tied)':''}: ${s.groups.filter(g=>g.score===Math.max(...s.groups.map(x=>x.score))).map(g=>g.name).join(', ')}.</div><div class="section-gap">${panel('The people behind the secrets',`<div class="player-list">${s.players.map(p=>`<div class="player"><span class="avatar">${p.id}</span><div class="info">${p.name}<small>${s.groups[p.group].name} · ${p.status}</small></div>${pill(p.role,p.role==='Traitor'?'red':'green')}</div>`).join('')}</div>`)}</div>`:`<div class="panel empty"><div class="seal">?</div><h2>The truth is still sealed.</h2><p style="margin-top:13px">After the final banishment, the host can release the winners.<br>Any surviving Traitor wins their group’s deduction game.</p></div>`)+`<div class="section-gap">${panel('Published timeline',s.published.map(e=>`<div class="log-entry"><time>${e.time}</time><span>${esc(e.group)} · ${esc(e.name)} · ${e.kind}${e.role?' · '+e.role:''}</span></div>`).join('')||'<p class="tiny muted">No eliminations have been published.</p>')}</div>`;}
function logs(){let entries=view==='nco'?s.log.filter(e=>e.text.includes(s.groups[group].name)||s.players.filter(p=>p.group===group).some(p=>e.text.includes(p.name))):s.log;return heading('ORGANISER AUDIT','A record of the evening.','Manual actions and corrections are recorded on this device.')+panel('Latest first',entries.map(e=>`<div class="log-entry"><time>${e.time}</time><span>${esc(e.text)}</span></div>`).join('')||'<p class="muted">The log begins when you take your first action.</p>');}
function settings(){
 return heading('','Settings','')+`<div class="dashboard-grid">${panel('Game setup',`<form id="settings-form" class="stack"><div class="form-grid"><label class="field">Groups<input type="number" id="group-count" min="1" max="5" value="${s.settings.groups}" ${s.assigned||s.identities?.length?'disabled':''}></label><label class="field">Players per group<input type="number" id="group-size" min="4" max="12" value="${s.settings.size}" ${s.assigned||s.identities?.length?'disabled':''}></label><label class="field">Traitors per group<input type="number" id="traitor-count" min="1" max="3" value="${s.settings.traitors}" ${s.assigned?'disabled':''}></label></div><label class="check"><input type="checkbox" id="shields" ${s.settings.shields?'checked':''}>Allow shields</label><label class="check"><input type="checkbox" id="chat" ${s.settings.chat?'checked':''}>Allow typed Traitor messages</label><label class="check"><input type="checkbox" id="decision-maker" ${s.settings.decisionMaker?'checked':''}>Lowest-numbered Traitor breaks disagreements</label><label class="check"><input type="checkbox" id="sound" ${s.settings.sound?'checked':''}>Timer sound</label><button class="gold" type="submit">Save settings</button></form>`)}<div class="stack">${panel('Connections',`<button disabled class="full">Connected mode unavailable</button><p class="subtitle">This demo runs on one browser. The database is not connected.</p><a href="guide.html#backend" target="_blank">Setup notes ↗</a>`)}${panel('Start over',`<p class="tiny muted" style="margin-bottom:15px">Clears local registrations and game progress.</p><div class="btns">${action('reset','Reset demo','danger')}${action('delete','Delete saved data','ghost')}</div>`)}</div></div>`;
}
function cadet(){
 const p=person(),g=s.groups[p.group],ph=phase(),v=s.votes[E.voteKey(s,p.group)],m=s.murders[E.murderKey(p.group,ph.slot??0)],alive=p.status==='Active',partners=E.active(s,p.group).filter(t=>t.role==='Traitor'&&t.id!==p.id);
 let secret='';
 if(!s.assigned)secret='<div class="waiting-card"><span class="seal">?</span><h2>You’re in.</h2><p>Wait for your NCO to release the roles.</p></div>';
 else if(alive)secret=`<div class="envelope"><div>${roleVisible?`<span class="eyebrow">YOUR ROLE</span><div class="revealed-role">${p.role}</div><p class="subtitle">${p.role==='Traitor'?'Keep your role secret. Survive the final vote.':'Find every Traitor in your group.'}</p>${p.role==='Traitor'?`<p style="margin:12px 0">Partners: ${partners.map(t=>esc(t.name)).join(', ')||'None'}</p>`:''}${action('hide-role','Hide role','small ghost')}`:`<div class="seal">24</div><button class="hold gold" id="hold-role">Hold to reveal your role</button>`}</div></div>`;
 else secret=`<div class="notice section-gap">You’re ${p.status.toLowerCase()}. Keep helping with missions.${p.role==='Traitor'?' Keep your former partners secret.':''}</div>`;
 let content='';
 if(ph.type==='mission')content+=`<div class="mission-brief section-gap"><span class="eyebrow">PHONES AWAY</span><p style="margin-top:12px">${esc(s.missions[ph.mission].instructions)}</p></div>`;
 if(ph.type==='vote'&&alive)content+=`<section class="section-gap"><h3>Your vote</h3>${v?.status==='open'?`<p class="subtitle">Choose one player. You can change until voting closes.</p><div class="vote-options section-gap">${E.active(s,p.group).filter(t=>t.id!==p.id&&(!v.candidates||v.candidates.includes(t.id))).map(t=>action('cadet-vote',esc(t.name),v.ballots[p.id]===t.id?'selected':'',`data-id="${t.id}" ${p.connected?'':'disabled'}`)).join('')}</div>${v.ballots[p.id]?`<p class="vote-receipt">✓ Vote saved locally: ${esc(E.getPlayer(s,v.ballots[p.id]).name)}</p>`:''}`:`<p class="subtitle">${v?'Voting closed. Wait for the reveal.':'Discuss with your group. Voting opens soon.'}</p>`}</section>`;
 if(p.role==='Traitor'&&alive&&roleVisible&&!s.ended)content+=`<section class="private-circle section-gap"><h3>Traitor circle</h3><p class="tiny muted" style="margin-top:6px">NCOs can read these messages.</p>${s.objectives[p.group]?`<div class="notice section-gap">${esc(s.objectives[p.group])}</div>`:''}${ph.slot!==undefined?`<form id="cadet-target-form" class="stack section-gap"><label class="field">Murder target<select id="cadet-target">${options(E.active(s,p.group).filter(t=>t.role==='Faithful'),m?.target)}</select></label><button type="submit" ${m?.confirmed||!p.connected?'disabled':''}>Confirm choice</button></form>${ph.slot===1?action('report-objective','Report objective complete','full section-gap',!p.connected||!m?'disabled':''):''}`:''}<div class="section-gap">${s.messages.filter(x=>x.group===p.group).slice(-4).map(x=>`<div class="chat-message"><small>${esc(x.from)}</small><p>${esc(x.text)}</p></div>`).join('')}</div><div class="btns">${['I agree','Suggest another target','Let’s wait for the NCO'].map(t=>action('preset',t,'small',`data-text="${esc(t)}" ${p.connected?'':'disabled'}`)).join('')}</div>${s.settings.chat?`<form id="chat-form" class="row section-gap"><input id="chat-text" aria-label="Private message" placeholder="Message…" maxlength="160" required><button type="submit" ${p.connected?'':'disabled'}>Send</button></form>`:''}</section>`;
 return `<div class="cadet-wrap"><section class="panel"><div class="cadet-top"><div class="row between"><div><span class="eyebrow">${esc(g.name)}</span><h2>${esc(p.name)}</h2></div>${pill(p.status,alive?'green':'red')}</div><p class="tiny muted">${g.score} points${p.connected?'':' · Signal lost: ask your NCO'}</p></div><div class="panel-body"><div class="row between"><h2>${esc(ph.name)}</h2><span class="timer" style="font-size:34px" data-timer>${time(s.remaining)}</span></div>${secret}${content}${s.announcements[0]?`<div class="announcement section-gap"><p>${esc(s.announcements[0].text)}</p></div>`:''}${s.ended?`<div class="notice section-gap">${E.results(s).find(x=>x.id===p.group).winner} win in ${esc(g.name)}.</div>`:''}<div class="btns section-gap">${action('help','Ask an NCO','ghost')}${action('rules','Rules','ghost')}</div></div></section></div>`;
}
const STEPS=[['Join as a cadet','Enter a name and the same four-digit PIN twice. This demo saves on this browser.'],['Open a secret','Hold the envelope button to reveal your role, then hide it.'],['Put phones away','Cadets get a brief mission card and return to their team.'],['Receive an instruction','Reveal the Traitor envelope to see an NCO objective and the private circle.'],['Cast a private vote','Select a player. The local acknowledgement is deliberately labelled as simulated.'],['Review as an NCO','Submission status is visible without showing a running tally.'],['A reveal for the room','Open the public display to see a published murder. No pending target is sent to it.'],['Stay part of the team','An eliminated cadet still sees missions and scores, with no secret actions.'],['Reveal the winners','Each circle has a deduction winner. Mission points are awarded separately.']];
function guideBar(){const step=STEPS[guide];return `<div class="guidebar"><span class="step">${guide+1}</span><div class="grow"><h3>${step[0]}</h3><p>${step[1]}</p></div><div class="btns">${action('guide-restart','Restart','small ghost')}${action('guide-exit','Leave','small ghost')}${action('guide-next',guide===8?'Finish tour ✓':'Next →','small gold')}</div></div>`;}
function render(){if(view==='welcome')$('app').innerHTML=(guide>=0?`<div style="padding:15px;background:#22251b">${guideBar()}</div>`:'')+welcome();else $('app').innerHTML=shell(view==='cadet'?cadet():({overview,groups,missions,voting,night,schedule,results,log:logs,settings}[page]??overview)());bindHold();}
function confirm(title,text,fn,label='Confirm'){const d=$('modal');d.innerHTML=`<h2>${esc(title)}</h2><p>${esc(text)}</p><div class="btns"><button id="cancel-modal">Cancel</button><button class="gold" id="confirm-modal">${esc(label)}</button></div>`;d.showModal();$('cancel-modal').onclick=()=>d.close();$('confirm-modal').onclick=()=>{d.close();run(fn);};}
function show(title,html){const d=$('modal');d.innerHTML=`<h2>${esc(title)}</h2>${html}<div class="btns"><button id="cancel-modal">Close</button></div>`;d.showModal();$('cancel-modal').onclick=()=>d.close();}
function run(fn){try{fn();save();render();}catch(e){toast(e.message);}}
function setPhase(i){E.requireThat(i>=0&&i<s.phases.length,'Invalid phase.');if(s.phase===5&&i>5){for(const g of s.groups){const m=s.murders[E.murderKey(g.id,1)];if(m&&!m.confirmed){E.confirmMurder(s,g.id,1,false);}}}s.phase=i;s.remaining=phase().mins*60;s.running=false;s.deadline=null;E.record(s,`Host moved to ${phase().name}.`);}
function simulateVotes(){E.requireThat(phase().type==='vote','Advance to a round table and open voting first.');const gs=view==='nco'?[s.groups[group]]:s.groups;let count=0;gs.forEach(g=>{if(g.done)return;let v=s.votes[E.voteKey(s,g.id)];if(!v){E.openVote(s,g.id);v=s.votes[E.voteKey(s,g.id)];}if(v.status!=='open')return;E.active(s,g.id).forEach(p=>{if(!p.connected)return;const targets=E.active(s,g.id).filter(t=>t.id!==p.id&&(!v.candidates||v.candidates.includes(t.id)));if(targets.length){E.castVote(s,g.id,p.id,E.shuffle(targets)[0].id);count++;}});});E.record(s,`${count} fictional votes simulated.`);toast(`${count} simulated votes saved on this device.`);}
function simulateMurder(){E.requireThat(s.assigned,'Assign roles first.');E.requireThat(phase().slot!==undefined,'Advance to a murder opportunity or The Vault.');const slot=phase().slot;let count=0;s.groups.forEach(g=>{const t=E.active(s,g.id).filter(p=>p.role==='Traitor'),f=E.active(s,g.id).filter(p=>p.role==='Faithful');if(t.length&&f.length&&!s.murders[E.murderKey(g.id,slot)]?.confirmed){const target=E.shuffle(f)[0];t.forEach(p=>E.propose(s,g.id,slot,p.id,target.id));count++;}});E.record(s,`Simulated murder proposals for ${count} groups; nothing published.`);toast('Choices simulated. Review them in Night operations.');}
function selectView(val){roleVisible=false;privateRoles=false;if(val==='host'){view='host';page='overview';return;}if(val==='nco'){view='nco';page='groups';return;}const candidates=s.players.filter(p=>val==='eliminated'?p.status!=='Active':p.status==='Active'&&(val==='traitor'?p.role==='Traitor':p.role!=='Traitor'));E.requireThat(candidates.length,val==='traitor'?'Assign roles before previewing a Traitor.':'No eliminated players yet. Publish an elimination or use the guided demo.');playerId=candidates[0].id;group=candidates[0].group;view='cadet';}
function message(text){const p=person();E.requireThat(p.status==='Active'&&p.role==='Traitor'&&p.connected,'Secret actions are only available to connected, active Traitors.');s.messages.push({group:p.group,from:p.name,text,time:new Date().toLocaleTimeString('en-GB')});}
function guideStep(n){guide=n;roleVisible=false;privateRoles=false;if(n===0){view='welcome';return;}if(!s.assigned)E.assign(s);const f=s.players.find(p=>p.role==='Faithful'&&p.status==='Active')??s.players.find(p=>p.role==='Faithful'),t=s.players.find(p=>p.role==='Traitor'&&p.status==='Active');group=f.group;if(n===1){setPhase(1);view='cadet';playerId=f.id;}if(n===2){setPhase(2);view='cadet';playerId=f.id;}if(n===3){E.requireThat(t,'Reset the demo to restore an active Traitor.');setPhase(5);view='cadet';playerId=t.id;group=t.group;s.objectives[t.group]='Persuade your assigned target to say “trust no one” during The Vault. Your NCO must confirm success.';const target=E.active(s,t.group).find(p=>p.role==='Faithful');if(!s.murders[E.murderKey(t.group,1)])E.propose(s,t.group,1,t.id,target.id);}if(n===4){setPhase(3);view='cadet';playerId=f.id;if(!s.votes[E.voteKey(s,group)])E.openVote(s,group);}if(n===5){setPhase(3);view='nco';page='voting';simulateVotes();}if(n===6){setPhase(4);view='host';page='night';const actor=E.active(s,group).find(p=>p.role==='Traitor');let m=s.murders[E.murderKey(group,0)];if(!m){E.propose(s,group,0,actor.id,E.active(s,group).find(p=>p.role==='Faithful').id);m=s.murders[E.murderKey(group,0)];}if(!m.confirmed)E.confirmMurder(s,group,0);if(!m.published)E.publishMurder(s,group,0);}if(n===7){setPhase(8);view='cadet';playerId=s.players.find(p=>p.status!=='Active').id;}if(n===8){setPhase(10);view='host';page='results';for(const [key,m]of Object.entries(s.murders)){if(m.confirmed&&!m.published){const [slot,g]=key.split(':').map(Number);E.publishMurder(s,g,slot);}}E.finish(s);}E.record(s,`Guided demonstration: step ${n+1}.`);}
function bindHold(){const b=$('hold-role');if(!b)return;const stop=()=>{clearTimeout(holdTimer);holdTimer=null;};const start=()=>{stop();holdTimer=setTimeout(()=>{roleVisible=true;render();},700);};b.addEventListener('pointerdown',e=>{e.preventDefault();b.setPointerCapture(e.pointerId);start();});b.addEventListener('pointerup',stop);b.addEventListener('pointercancel',stop);b.addEventListener('pointerleave',stop);b.addEventListener('keydown',e=>{if([' ','Enter'].includes(e.key)&&!e.repeat){e.preventDefault();start();}});b.addEventListener('keyup',stop);b.addEventListener('blur',stop);}
document.addEventListener('visibilitychange',()=>{if(document.hidden){clearTimeout(holdTimer);roleVisible=false;privateRoles=false;if(view==='cadet')render();}});
document.addEventListener('change',e=>{if(e.target.id==='view-switch')run(()=>selectView(e.target.value));});
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b||b.disabled)return;const a=b.dataset.action;run(()=>{switch(a){
case 'start':view='host';page='overview';break;
case 'welcome':view='welcome';roleVisible=false;break;
case 'page':page=b.dataset.page;roleVisible=false;privateRoles=false;break;
case 'group':group=Number(b.dataset.group);page='groups';break;
case 'select-group':group=Number(b.dataset.group);privateRoles=false;break;
case 'nco':view='nco';page='groups';break;
case 'roles':privateRoles=!privateRoles;break;
case 'projector':save();window.open('projector.html','tno-projector');break;
case 'timer':if(s.running){s.remaining=Math.max(0,Math.ceil((s.deadline-Date.now())/1000));s.running=false;s.deadline=null;}else{s.deadline=Date.now()+s.remaining*1000;s.running=true;}E.record(s,`Timer ${s.running?'started':'paused'} in ${phase().name}.`);break;
case 'extend':s.remaining+=60;if(s.running)s.deadline+=60000;E.record(s,'Timer extended by one minute.');break;
case 'advance':confirm('Advance the evening?',`Move to ${s.phases[s.phase+1]?.name}. Unconfirmed secret attempts expire as failures when leaving The Vault. No result will be published automatically.`,()=>setPhase(s.phase+1),'Advance phase');break;
case 'jump':confirm('Move to this phase?',`Set the demo to ${s.phases[Number(b.dataset.index)].name}. The timer will be paused. Leaving The Vault expires unresolved secret attempts.`,()=>setPhase(Number(b.dataset.index)));break;
case 'assign':confirm('Close joining and assign roles?',`Assign ${s.settings.traitors} Traitors per group and release private envelopes. Roles will persist on this device.`,()=>E.assign(s),'Assign & release');break;
case 'sim-votes':simulateVotes();break;
case 'sim-murder':simulateMurder();break;
case 'disconnect':{const p=E.shuffle(s.players.filter(p=>p.connected))[0];E.requireThat(p,'Everyone is already disconnected.');p.connected=false;E.record(s,`${p.name} simulated signal loss. Not eliminated.`);toast(`${p.name} disconnected. Restore access from Groups & players.`);break;}
case 'help':{const p=person();if(!s.helps.some(h=>h.id===p.id&&!h.done))s.helps.push({id:p.id,done:false});E.record(s,`${p.name} requested help.`);toast('Demo help request saved. The group NCO can acknowledge it.');break;}
case 'help-done':s.helps.filter(h=>h.id===Number(b.dataset.id)).forEach(h=>h.done=true);E.record(s,`${E.getPlayer(s,b.dataset.id).name}: help request acknowledged.`);break;
case 'open-vote':E.openVote(s,group);break;
case 'close-vote':confirm('Close this group’s ballot?','Unsubmitted votes will be recorded as abstentions. The result stays private until the host releases it.',()=>E.closeVote(s,group),'Close ballot');break;
case 'runoff':E.runoff(s,group);s.remaining=60;if(s.running)s.deadline=Date.now()+60000;break;
case 'random-tie':confirm('Draw between tied candidates?','This follows one tied runoff. The randomly selected candidate will be recorded in the event log.',()=>E.randomTie(s,group),'Run random draw');break;
case 'publish-banish':confirm('Publish this banishment?','Everyone will see the player’s name first. You can reveal their role separately. Public information cannot become secret again.',()=>E.publishBanish(s,group),'Publish name');break;
case 'reveal-role':confirm('Reveal the banished player’s role?','This makes their identity public and cannot meaningfully be undone.',()=>E.revealRole(s),'Reveal role');break;
case 'confirm-murder':confirm('Confirm the private outcome?','Confirm physical success if applicable. Eligibility and shields are checked in this demo engine. The victim stays off the public display until publication.',()=>E.confirmMurder(s,group,phase().slot??0),'Confirm privately');break;
case 'fail-murder':E.confirmMurder(s,group,phase().slot??0,false);break;
case 'publish-murder':confirm('Release the night’s outcome?','This publishes the confirmed outcome and updates player status. Only one victim is allowed for this opportunity.',()=>E.publishMurder(s,group,phase().slot??0),'Publish reveal');break;
case 'hide-role':roleVisible=false;break;
case 'cadet-vote':{const p=person();E.requireThat(p.connected,'Simulated signal loss. Ask your NCO to restore access.');E.castVote(s,p.group,p.id,Number(b.dataset.id));toast('Vote saved locally. You can change it until voting closes.');break;}
case 'preset':message(b.dataset.text);break;
case 'report-objective':message('I report the objective completed. Awaiting NCO verification.');E.record(s,`${person().name} reported secret objective completion; not yet confirmed.`);break;
case 'rules':show('A quick reminder',`<p>Work with your group on physical missions. During a round table, vote for an active player in your own group. You cannot vote for yourself.</p><p>Keep accusations about game actions. Eliminated players still help with missions and scores, but cannot vote or use private Traitor actions. Tell your NCO if you need help.</p>`);break;
case 'mission-detail':{const m=s.missions[Number(b.dataset.index)];show(m.title,`<p>${esc(m.instructions)}</p><div class="notice">Up to ${m.points} points. Physical completion must be confirmed by the NCO.</div>`);break;}
case 'mission-edit':{const i=Number(b.dataset.index),m=s.missions[i];show('Edit mission card',`<form id="mission-form" data-index="${i}" class="stack"><label class="field">Title<input id="mission-title" value="${esc(m.title)}" maxlength="60" required></label><label class="field">Summary<textarea id="mission-description" required>${esc(m.description)}</textarea></label><label class="field">Instructions<textarea id="mission-instructions" required>${esc(m.instructions)}</textarea></label><label class="field">Maximum points<input id="mission-points" type="number" min="0" max="1000" value="${m.points}" required></label><button class="gold" type="submit">Save mission</button></form>`);break;}
case 'player-tools':{const p=E.getPlayer(s,b.dataset.id);show(`Manage ${p.name}`,`<form id="player-form" data-id="${p.id}" class="stack"><label class="field">Optional callsign<input id="callsign" value="${esc(p.callsign??'')}" maxlength="24" placeholder="No personal names required"></label><label class="field">Player status<select id="player-status">${['Active','Banished','Murdered'].map(t=>`<option ${t===p.status?'selected':''}>${t}</option>`).join('')}</select></label><label class="check"><input type="checkbox" id="player-connected" ${p.connected?'checked':''}>Restore / retain simulated connection</label><label class="check"><input type="checkbox" id="player-shield" ${p.shield?'checked':''} ${s.settings.shields?'':'disabled'}>Shield (${s.settings.shields?'enabled':'disabled in settings'})</label><label class="field">Reason for manual change<input id="correction-reason" required maxlength="180" placeholder="Explain the correction or access recovery"></label><div class="notice">A publicly revealed identity cannot become secret again. Status corrections do not remove published history.</div><button class="gold" type="submit">Review change</button></form>`);break;}
case 'late':{const i=s.phases.findIndex((p,i)=>i>=s.phase&&p.type==='mission'&&p.mins>5);E.requireThat(i>=0,'No remaining mission can be shortened. Keep the finale and clear up protected.');confirm('Recover five minutes?',`Shorten ${s.phases[i].name} by five minutes. Finale, clear up and parade stay unchanged. This is a suggested time saving, not automatic rescheduling.`,()=>{s.phases[i].mins-=5;if(i===s.phase){s.remaining=Math.max(0,s.remaining-300);if(s.running)s.deadline=Date.now()+s.remaining*1000;}E.record(s,`Running late: shortened ${s.phases[i].name} by five minutes.`);},'Shorten mission');break;}
case 'finish':confirm('End the game and reveal every role?','Any remaining Traitor wins their group. Confirmed murder outcomes must be published first. This releases all roles publicly.',()=>E.finish(s),'Reveal winners');break;
case 'reset':confirm('Start a fresh rehearsal?','This clears progress, roles, votes, scores and the organiser log on this device.',()=>{s=E.initial();guide=-1;view='host';page='overview';group=0;playerId=1;roleVisible=false;},'Reset demo');break;
case 'delete':confirm('Delete this demo’s stored game data?','Removes the local game and public snapshot from this browser. Reloading will offer a fresh fictional demo.',()=>{localStorage.removeItem(KEY);localStorage.removeItem(PUB);s=E.initial();guide=-1;view='welcome';render();setTimeout(()=>{localStorage.removeItem(KEY);localStorage.removeItem(PUB);},0);},'Delete data');break;
case 'guide':case 'guide-restart':confirm('Start the staff walkthrough?','The guided tour uses a fresh simulated event and replaces current rehearsal progress. It demonstrates role assignment, a murder publication and the final reveal.',()=>{s=E.initial();group=0;guideStep(0);},'Start walkthrough');break;
case 'guide-next':if(guide===8){guide=-1;toast('Walkthrough complete. Reset for a full rehearsal.');}else guideStep(guide+1);break;
case 'guide-exit':guide=-1;break;
}});});
document.addEventListener('submit',e=>{e.preventDefault();const f=e.target;if(f.id==='join-form'){void joinByName(f);return;}run(()=>{switch(f.id){
case 'announce-form':{const text=$('announcement').value.trim();E.requireThat(text,'Enter an announcement.');s.announcements.unshift({text,time:new Date().toLocaleTimeString('en-GB')});E.record(s,'Host published an announcement.');toast('Announcement published to the local demo.');break;}
case 'score-form':{const delta=Number($('score-delta').value),reason=$('score-reason').value.trim();E.requireThat(Number.isFinite(delta)&&reason,'Enter points and a reason.');s.groups[group].score+=delta;E.record(s,`${s.groups[group].name}: ${delta>=0?'+':''}${delta} mission points. ${reason}`);break;}
case 'proxy-form':E.castVote(s,group,Number($('proxy-voter').value),Number($('proxy-target').value),true);toast('Proxy vote saved locally and logged.');break;
case 'murder-form':E.propose(s,group,phase().slot??0,Number($('murder-actor').value),Number($('murder-target').value));E.record(s,`${s.groups[group].name}: NCO recorded a murder proposal.`);break;
case 'objective-form':s.objectives[group]=$('objective').value.trim();E.record(s,`${s.groups[group].name}: NCO sent a private objective.`);toast('Objective saved to the active Traitor view.');break;
case 'cadet-target-form':{const p=person();E.requireThat(p.connected,'Restore your connection first.');E.propose(s,p.group,phase().slot??0,p.id,Number($('cadet-target').value));toast('Target choice saved locally; NCO confirmation required.');break;}
case 'chat-form':message($('chat-text').value.trim());break;
case 'mission-form':{const i=Number(f.dataset.index);s.missions[i]={title:$('mission-title').value.trim(),description:$('mission-description').value.trim(),instructions:$('mission-instructions').value.trim(),points:Number($('mission-points').value)};s.phases[[2,5,8][i]].name=s.missions[i].title;E.record(s,`Mission ${i+1} edited.`);$('modal').close();break;}
case 'schedule-form':{const next=s.phases.map((p,i)=>({...p,time:$('start-'+i).value,mins:Number($('mins-'+i).value)}));E.requireThat(next.every((p,i)=>!i||p.time>next[i-1].time),'Start times must increase through the evening.');s.phases=next;if(!s.running)s.remaining=phase().mins*60;E.record(s,'Host edited the event timetable.');toast('Timetable saved. Check finale and clear up times before the event.');break;}
case 'settings-form':{
  if(!s.assigned){
    const groups=Number($('group-count').value),size=Number($('group-size').value),traitors=Number($('traitor-count').value);
    E.requireThat(traitors<size,'Keep at least one Faithful per group.');
    const resized=groups!==s.settings.groups||size!==s.settings.size;
    if(resized)E.requireThat(!(s.identities?.length),'Players have joined. Reset the demo before resizing the roster.');
    s.settings={...s.settings,groups,size,traitors};
    if(resized){
      s.groups=E.GROUPS.slice(0,groups).map((name,id)=>({id,name,score:0,done:false}));
      s.players=Array.from({length:groups*size},(_,i)=>({id:i+1,name:'Player '+String(i+1).padStart(2,'0'),group:Math.floor(i/size),role:null,status:'Active',connected:true,shield:false}));
      s.identities=[];group=Math.min(group,groups-1);
    }
  }
  s.settings.shields=$('shields').checked;s.settings.chat=$('chat').checked;
  s.settings.decisionMaker=$('decision-maker').checked;s.settings.sound=$('sound').checked;
  E.record(s,'Host updated event settings.');toast('Settings saved.');break;
}
case 'player-form':{const p=E.getPlayer(s,f.dataset.id),status=$('player-status').value,connected=$('player-connected').checked,shield=$('player-shield').checked,callsign=$('callsign').value.trim(),reason=$('correction-reason').value.trim();$('modal').close();confirm('Apply the player correction?',`${p.name}: ${status}. ${reason} Any previously public role remains known.`,()=>{p.status=status;p.connected=connected;p.shield=shield;p.callsign=callsign;p.name=p.displayName||`Player ${String(p.id).padStart(2,'0')}${callsign?' · '+callsign:''}`;s.groups[p.group].done=false;E.checkGroup(s,p.group);E.record(s,`${p.name}: manual correction (${status}, ${connected?'connected':'disconnected'}). Reason: ${reason}`);});break;}
}});});
setInterval(()=>{if(!s.running)return;s.remaining=Math.max(0,Math.ceil((s.deadline-Date.now())/1000));document.querySelectorAll('[data-timer]').forEach(n=>n.textContent=time(s.remaining));if(s.remaining===0){s.running=false;s.deadline=null;E.record(s,`Timer ended: ${phase().name}. Awaiting organiser action.`);toast('Time is up. The organiser decides what happens next.');if(s.settings.sound){try{const c=new AudioContext(),o=c.createOscillator(),g=c.createGain();o.connect(g);g.connect(c.destination);g.gain.value=.08;o.frequency.value=440;o.start();o.stop(c.currentTime+.3);o.onended=()=>c.close();}catch{}}save();render();}else save();},1000);
